pub fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of input rows and columns
    let n_rows = x.len();
    let n_cols = x[0].len();

    // Prepare the result with n_cols rows, each of capacity n_rows
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(n_cols);

    // Build each of the n_cols rows of the transpose
    for c in 0..n_cols {
        // Invariant after k iterations of the outer loop (here k == c):
        //   1) result.len() == c
        //   2) Each built-up result[i] has length == n_rows
        //   3) For all built entries, result[i][j] = x[j][i]
        #[invariant(result.len() == c)]
        #[invariant(forall(|i: usize| i < c ==> result[i].len() == n_rows))]
        #[invariant(forall(|i: usize, j: usize| i < c && j < n_rows ==> result[i][j] == x[j][i]))]
        #[decreases(n_cols - c)]
        {
            let mut new_row: Vec<f32> = Vec::with_capacity(n_rows);

            // Fill in the c-th row of the transpose by pulling x[r][c]
            for r in 0..n_rows {
                // Invariant after t iterations of the inner loop (t == r):
                //   new_row.len() == r
                //   new_row[j] == x[j][c] for all j < r
                #[invariant(new_row.len() == r)]
                #[invariant(forall(|j: usize| j < r ==> new_row[j] == x[j][c]))]
                #[decreases(n_rows - r)]
                {
                    new_row.push(x[r][c]);
                }
            }

            result.push(new_row);
        }
    }

    result
}


